#!/usr/bin/env node
// The viewer has ONE source (docs/history/HANDOFF_PLAN.md, rule 1). Everything else is a copy and must hold the same bytes:
//   skill/assets/viewer.html  = web/index.html        skill/assets/dev.html = web/dev.html
//   desktop/app/index.html    = web/index.html        desktop/app/dev.html  = web/dev.html   (only if desktop/app exists:
//                                                      it is generated by `node desktop/scripts/sync.js` and not in git)
// Line endings are normalised to LF before hashing, so a Windows checkout with core.autocrlf compares the same as CI.
//   node tools/check-copies.mjs        exit 1 and list the copies that differ
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sha = (f) => crypto.createHash('sha256').update(fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n')).digest('hex');
const PAIRS = [
  ['web/index.html', 'skill/assets/viewer.html', true],
  ['web/dev.html', 'skill/assets/dev.html', true],
  ['web/index.html', 'desktop/app/index.html', false],
  ['web/dev.html', 'desktop/app/dev.html', false],
];
let bad = 0;
for (const [src, copy, required] of PAIRS) {
  const a = path.join(ROOT, src), b = path.join(ROOT, copy);
  if (!fs.existsSync(b)) { if (required) { console.log(`✗ ${copy} 不存在`); bad++; } else console.log(`- ${copy} 不存在（跳过；先运行 node desktop/scripts/sync.js）`); continue; }
  const ha = sha(a), hb = sha(b);
  if (ha === hb) console.log(`✓ ${copy} = ${src}  ${ha.slice(0, 16)}…`);
  else { console.log(`✗ ${copy} 与 ${src} 不一致：${hb.slice(0, 16)}… ≠ ${ha.slice(0, 16)}…`); bad++; }
}
if (bad) { console.log(`\n${bad} 个副本不一致。修正：node tools/sync-copies.mjs（或手动复制源文件），然后重新提交。`); process.exit(1); }
console.log('\n所有副本一致。');
